padding: 0.5rem 1rem;
font-family: var(--p-font-monospace);
}

/* Page Options Bottom */

div#main-content #page-options-bottom, div#main-content #page-options-bottom-2 {
margin: 0rem auto;
width: min(90vw, calc(var(--p-main-content-max-width) - 8rem));
