}

#action-area .buttons.alignleft {
display: flex;
justify-content: space-between;
flex-wrap: wrap;
gap: 0.5rem;
}

#action-area input#edit-cancel-button {
color: var(--p-warning-color);
}

#action-area input#edit-cancel-button:hover {
