}

#history-form-1 #h-perpage {
padding: 0.35rem 0.5rem;
border: none;
border-radius: var(--p-border-radius-medium);
background-color: var(--p-gray-2);
color: var(--p-gray-5);
font-size: var(--p-font-size-base);
cursor: pointer;
}

#history-form-1 #h-perpage:hover {
