}

/* Display Black Block by Nanimono Demonai */

.bblock {
color: var(--p-gray-5);
background-color: var(--p-gray-5);
transition: 2s;
text-decoration: none;
}

.bblock:hover {
background-color: var(--p-gray-5);
color: var(--p-gray-1);
text-decoration: none;
}

.dblock {
color: var(--p-gray-5);
background-color: var(--p-gray-5);
transition: 2s;
