}

/* odate fix */

.odate {
display: inline;
}

/* Credit */

:is(#u-credit-otherwise, #u-credit-view) {
max-width: 100% !important;
}

:is(#u-credit-otherwise, #u-credit-view) .modalbox {
background: var(--p-gray-0);
color: var(--p-gray-5);
box-shadow: var(--p-shadow-2);
border-radius: var(--p-border-radius-medium);
