flex-direction: column;
align-items: center;
justify-content: center;
padding: 0rem;
}

:is(#u-credit-otherwise, #u-credit-view) .modalbox > div:first-child {
padding: 1.25rem 2rem;
border-bottom: 0.1rem solid var(--p-gray-2);
