}

:is(#u-credit-otherwise, #u-credit-view) .modalbox .close-credits {
display: contents;
}

/* User Info */

ul#ui-tabs.nav {
display: grid;
grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr));
gap: 0.75rem;
}

ul#ui-tabs.nav li {
display: contents;
}

ul#ui-tabs.nav li a:hover, ul#ui-tabs.nav li.active a {
