border: var(--p-modal-border);
margin: var(--p-blockquote-margin);
border-radius: var(--p-modal-border-radius);
}

.notation,
.p-no {
width: calc(100% - (var(--p-blockquote-padding-x) * 2) - (var(--p-notation-border-width) * 2));
