padding: 0.4rem 1rem;
border-radius: var(--p-border-radius-small);
}

.forum-group div.head {
background-color: var(--p-gray-4);
color: var(--p-gray-1);
padding: 0.5rem 1rem;
margin: 0;
border: none;
border-radius: var(--p-border-radius-small);
}

.forum-group table td {
