}

.forum-thread-box .description-block .statistics a {
color: var(--p-theme-color-light);
}
.forum-thread-box .description-block .statistics {
color: var(--p-gray-1);
}

.thread-container .post .head {
padding: 0.5rem 1rem;
background-color: var(--p-gray-1);
