}

.thread-container .post .long .revisions table tr.active td {
background-color: transparent;
}

.thread-container .post .long .revisions table tr.active td:first-child::before {
content: '当前';
display: inline-block;
position: absolute;
transform: translate(-2.7rem, -0.1rem);
color: var(--p-gray-7);
background-color: var(--p-gray-2);
font-size: 85%;
padding: 0.2rem 0.5rem;
border-radius: var(--p-border-radius-small);
